/* ???? Fondo personalizado para YouTube */
@-moz-document domain("youtube.com") {
body,
  ytd-app {
    background: url("https://files.oaiusercontent.com/file-00000000f15c720e8e17417e80771b68") no-repeat center center fixed !important;
    background-size: cover !important;
    background-attachment: fixed !important;
  }

  /* Fondo semi-transparente para mantener legibilidad */
  #content, 
  ytd-page-manager, 
  ytd-watch-flexy, 
  ytd-browse, 
  ytd-search,
  #page-manager {
    background: rgba(0, 0, 0, 0.6) !important;
    backdrop-filter: blur(6px);
  }

  /* Cambiar colores de texto para contraste */
  ytd-video-primary-info-renderer,
  ytd-video-secondary-info-renderer,
  ytd-comments,
  #meta,
  #description {
    color: #f5f5f5 !important;
  }

  /* Enlaces y botones en tono rojo */
  a, 
  .yt-simple-endpoint,
  paper-button {
    color: #ff3b3b !important;
  }

  /* Oculta el fondo blanco de cabecera y menú */
  #masthead-container,
  #container.ytd-masthead,
  tp-yt-app-drawer {
    background: transparent !important;
    backdrop-filter: blur(4px);
  }
}
